import { issueCommand, requiresApproval, classifyRisk } from '@projexlight/sdk-command';

const cmd = await issueCommand({
  tenant_id: req.auth.tenant_id,
  target_asset_id: assetId,
  type: 'estop',
  params: { reason: 'obstacle detected' },
  issued_by: req.auth.sub,
});
// classifyRisk('estop') === 'high' => requiresApproval(cmd.risk_class) === true
console.log(cmd.status); // 'pending' (gated, awaiting approval grant)

import { applyCommandApprovalDecision, dispatchCommand, getCommandBroker } from '@projexlight/sdk-command';

const approved = await applyCommandApprovalDecision(tenantId, commandId, {
  approved: true,
  decided_by: approverId,
  reason: 'safe to proceed',
});

const unsub = getCommandBroker().subscribe(approved.target_asset_id, (e) => sendToRobotWs(e));
const dispatched = await dispatchCommand(tenantId, commandId);
console.log(dispatched?.status); // 'dispatched'

import { issueRobotCredential, ackCommandWithCredential } from '@projexlight/sdk-command';

const cred = await issueRobotCredential({ tenant_id: tenantId, asset_id: assetId });
// cred.plaintext is returned once; store it on the robot securely.

const result = await ackCommandWithCredential(cred.plaintext, commandId, {
  ok: true,
  code: 'DONE',
  data: { position: [1.2, 0.4, 0.0] },
});
console.log(result.outcome); // 'ok'
